def svg(name: str, color: str) -> str:
    body = P.get(name, P["dot"]).replace("currentColor", color)
    return (f'<svg xmlns="http://www.w3.org/2000/svg" viewBox="0 0 24 24" fill="none" stroke="{color}" '
            f'stroke-width="2" stroke-linecap="round" stroke-linejoin="round">{body}</svg>')


@lru_cache(maxsize=512)
def pixmap(name: str, color: str = "#E6ECEA", size: int = 20) -> QPixmap:
    scale = 2
    pm = QPixmap(size * scale, size * scale)
    pm.fill(Qt.transparent)
    r = QSvgRenderer(QByteArray(svg(name, color).encode()))
    p = QPainter(pm)
    r.render(p, QRectF(0, 0, size * scale, size * scale))
    p.end()
    pm.setDevicePixelRatio(scale)
    return pm


def icon(name: str, color: str = "#E6ECEA", size: int = 20) -> QIcon:
    return QIcon(pixmap(name, color, size))
